/**
 * Named constants for transcript normalization — the tool that turns a raw
 * upload (.vtt, .txt, .doc, .docx) into the normalized markdown transcript.
 * Everything here is deterministic: the only randomness in the whole pipeline
 * is the per-ingest TranscriptID, generated by the tool's caller contract.
 */

/** Separator between a line number and the transcript line it labels, in the
 * stable `NN |` prefixes every downstream prompt reads. */
export const LINE_NUMBER_SEPARATOR = ' | ';

/** File extension that marks an upload as WebVTT. */
export const VTT_FILE_EXTENSION = '.vtt';

/** File extension that marks an upload as a zipped Office (Word) document. */
export const DOCX_FILE_EXTENSION = '.docx';

/** File extension that marks an upload as a legacy binary Word document. */
export const DOC_FILE_EXTENSION = '.doc';

/** First token of a WebVTT file; used to sniff VTT input when the extension
 * gives nothing away. */
export const WEBVTT_HEADER_PREFIX = 'WEBVTT';

/** First four bytes of a ZIP local file header — the magic every .docx
 * (a zipped Office document) starts with. */
export const ZIP_LOCAL_HEADER_MAGIC = 'PK\x03\x04';

/** First four bytes of an OLE2 compound file — the magic every legacy .doc
 * starts with. */
export const OLE_FILE_MAGIC = '\xD0\xCF\x11\xE0';

/** Suffix for the normalized markdown transcript written beside the
 * untouched original in the meeting directory. */
export const NORMALIZED_TRANSCRIPT_SUFFIX = '.normalized.md';

/** The one entry of a .docx archive that carries the document body text. */
export const DOCX_BODY_ENTRY_PATH = 'word/document.xml';

/** A GUID-shaped cue identifier (WebVTT cue ids are free-form text; only
 * this exact shape counts as a candidate MeetingID). */
export const GUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
